with source as (
    select * from {{ ref('stg_origo_deals') }}
),

deal_resolution as (
    select * from {{ ref('res_deal') }}
),

fund_lookup as (
    select * from {{ ref('int_deal_conversion_fund') }}
)

select
    source.source_deal_id as source_deal_id,
    source.converted_record_type as converted_record_type,
    source.converted_record_id as converted_record_id,
    source.sourced_date as effective_from,
    deal_resolution.golden_deal_key as golden_deal_key,
    fund_lookup.golden_fund_key as golden_fund_key
from source
inner join deal_resolution
    on deal_resolution.source_system = source.source_system
    and deal_resolution.source_id = source.source_deal_id
    and deal_resolution.source_record_id = source.source_record_id
left join fund_lookup
    on fund_lookup.fund_external_id = source.converted_record_id
where deal_resolution.golden_deal_key is not null
    and fund_lookup.golden_fund_key is not null
